-- ============================================================
-- 004_curriculum_v1.sql — Seed Curriculum v1, Days 2–30 (spec §10)
-- DB-driven, editable by Admin. Trilingual en / ms-MY / id-ID.
-- Phases: 1 Foundation(1-5) · 2 Prospecting(6-12) · 3 Presentation(13-21) · 4 Closing(22-30)
-- ============================================================

insert into curriculum_days (version_id, day_no, phase, title, objective, content, required_action, evidence_requirement, reflection_question, xp_amount, needs_review)
select v.id, x.day_no, x.phase,
  x.title::jsonb, x.objective::jsonb, x.content::jsonb,
  x.required_action::jsonb, x.evidence::jsonb, x.reflection::jsonb,
  x.xp, true
from curriculum_versions v
cross join (values
-- ===== PHASE 1 (2-5) =====
(2,1,
 '{"en":"Professional Identity & Character","ms-MY":"Identiti Profesional & Sahsiah","id-ID":"Identitas Profesional & Karakter"}',
 '{"en":"Define who you are as a professional; strengths, gaps, conduct.","ms-MY":"Tentukan identiti profesional anda; kekuatan, kelemahan, tatakelakuan.","id-ID":"Tetapkan identitas profesional Anda; kekuatan, kelemahan, etika."}',
 '{"en":"Character comes before commission. Your name is your brand — protect it with integrity in every interaction.","ms-MY":"Sahsiah sebelum komisen. Nama anda ialah jenama anda — jaga dengan integriti.","id-ID":"Karakter sebelum komisi. Nama Anda adalah merek Anda — jaga dengan integritas."}',
 '{"en":"Complete your professional profile and write a character reflection.","ms-MY":"Lengkapkan profil profesional dan tulis refleksi sahsiah.","id-ID":"Lengkapi profil profesional dan tulis refleksi karakter."}',
 '{"en":"Completed profile + character reflection + improvement commitment","ms-MY":"Profil lengkap + refleksi sahsiah + komitmen penambahbaikan","id-ID":"Profil lengkap + refleksi karakter + komitmen perbaikan"}',
 '{"en":"Which strength will you use most, and which gap will you fix first?","ms-MY":"Kekuatan mana anda guna paling banyak, kelemahan mana anda baiki dulu?","id-ID":"Kekuatan mana yang paling Anda pakai, kelemahan mana yang diperbaiki dulu?"}',
 10),
(3,1,
 '{"en":"System & Work Setup","ms-MY":"Persediaan Sistem & Kerja","id-ID":"Penyiapan Sistem & Kerja"}',
 '{"en":"Complete approved account, social, project and work-system setup.","ms-MY":"Lengkapkan persediaan akaun, sosial, projek dan sistem kerja.","id-ID":"Selesaikan penyiapan akun, sosial, proyek dan sistem kerja."}',
 '{"en":"A warrior with sharp tools moves fast. Confirm access to every approved tool today. Never share passwords.","ms-MY":"Warrior dengan alat lengkap bergerak pantas. Sahkan akses semua alat hari ini. Jangan kongsi kata laluan.","id-ID":"Warrior dengan alat lengkap bergerak cepat. Pastikan akses semua alat hari ini. Jangan bagikan kata sandi."}',
 '{"en":"Finish the setup checklist and confirm tool access.","ms-MY":"Siapkan senarai semak persediaan dan sahkan akses alat.","id-ID":"Selesaikan checklist penyiapan dan konfirmasi akses alat."}',
 '{"en":"Readiness checklist + approved confirmation (no passwords/secrets)","ms-MY":"Senarai semak + pengesahan (tanpa kata laluan/rahsia)","id-ID":"Checklist + konfirmasi (tanpa kata sandi/rahasia)"}',
 '{"en":"Which tool will save you the most time daily?","ms-MY":"Alat mana paling menjimatkan masa anda setiap hari?","id-ID":"Alat mana yang paling menghemat waktu Anda setiap hari?"}',
 10),
(4,1,
 '{"en":"Market, Customer & Project Focus","ms-MY":"Fokus Pasaran, Pelanggan & Projek","id-ID":"Fokus Pasar, Pelanggan & Proyek"}',
 '{"en":"Choose an approved market/project focus and define your customer.","ms-MY":"Pilih fokus pasaran/projek yang diluluskan dan kenal pasti pelanggan.","id-ID":"Pilih fokus pasar/proyek yang disetujui dan kenali pelanggan Anda."}',
 '{"en":"Focus beats spray-and-pray. One market, one customer profile, one approved value story — mastered.","ms-MY":"Fokus mengalahkan bedil rambang. Satu pasaran, satu profil pelanggan, satu cerita nilai.","id-ID":"Fokus mengalahkan asal tembak. Satu pasar, satu profil pelanggan, satu cerita nilai."}',
 '{"en":"Select your focus, write the customer profile, finish the approved project learning.","ms-MY":"Pilih fokus, tulis profil pelanggan, habiskan pembelajaran projek.","id-ID":"Pilih fokus, tulis profil pelanggan, selesaikan pembelajaran proyek."}',
 '{"en":"Selected focus + customer profile + project-learning completion","ms-MY":"Fokus + profil pelanggan + pembelajaran projek selesai","id-ID":"Fokus + profil pelanggan + pembelajaran proyek selesai"}',
 '{"en":"Why does this customer need this project?","ms-MY":"Mengapa pelanggan ini perlukan projek ini?","id-ID":"Mengapa pelanggan ini membutuhkan proyek ini?"}',
 10),
(5,1,
 '{"en":"Build the First Lead List","ms-MY":"Bina Senarai Lead Pertama","id-ID":"Bangun Daftar Lead Pertama"}',
 '{"en":"Prepare an initial contact list and an ethical outreach plan.","ms-MY":"Sediakan senarai kenalan awal dan pelan hubungan beretika.","id-ID":"Siapkan daftar kontak awal dan rencana pendekatan yang etis."}',
 '{"en":"Your network is your first pipeline. List contacts respectfully — no unnecessary personal information.","ms-MY":"Rangkaian anda ialah pipeline pertama. Senaraikan kenalan dengan hormat.","id-ID":"Jaringan Anda adalah pipeline pertama. Daftarkan kontak dengan hormat."}',
 '{"en":"Create your first lead records and plan the first actions.","ms-MY":"Cipta rekod lead pertama dan rancang tindakan pertama.","id-ID":"Buat catatan lead pertama dan rencanakan aksi pertama."}',
 '{"en":"Lead records created + planned first actions","ms-MY":"Rekod lead dicipta + tindakan pertama dirancang","id-ID":"Catatan lead dibuat + aksi pertama direncanakan"}',
 '{"en":"Who are your 5 warmest contacts and why?","ms-MY":"Siapa 5 kenalan paling hangat anda dan mengapa?","id-ID":"Siapa 5 kontak terhangat Anda dan mengapa?"}',
